const state={user:null,csrf:sessionStorage.getItem('audit_csrf')||'',projects:[],project:null,view:'Overview',filter:{q:'',severity:'',status:''},scanTimer:null};
const $=(s,r=document)=>r.querySelector(s); const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cookie=n=>document.cookie.split('; ').find(x=>x.startsWith(n+'='))?.split('=').slice(1).join('=')||'';
async function api(path,opts={}){const headers={'Content-Type':'application/json',...(opts.headers||{})};if(opts.method&&opts.method!=='GET')headers['X-CSRF-Token']=state.csrf||decodeURIComponent(cookie('audit_csrf'));const base=(window.AUDIT_API_URL||'').replace(/\/$/,'');const r=await fetch(base+'/api'+path,{...opts,headers,credentials:'include'});if(!r.ok){let e={};try{e=await r.json()}catch{};if(r.status===401){state.user=null;login();}throw Error(e.error||`Request failed (${r.status})`)}const type=r.headers.get('content-type')||'';return type.includes('json')?r.json():r;}
function toast(s,bad=false){const el=$('#toast');if(!el)return;el.textContent=s;el.className='toast show '+(bad?'bad':'');setTimeout(()=>el.className='toast',3200)}
window.addEventListener('sentinel:reset-view',()=>resetCurrentView().catch(err=>toast(`Reset failed: ${err.message}`,true)));
async function resetCurrentView(){const modalForm=$('#modal form');if(modalForm&&[...new FormData(modalForm).values()].some(v=>String(v).trim())){if(!confirm('Discard unsaved form changes and reset this page view? Saved assessments and findings will remain unchanged.'))return}state.filter={q:'',severity:'',status:''};closeModal();if(!state.user){const form=$('#login');form?.reset();form?.elements.email?.focus();toast('Sign-in form cleared · saved data unchanged');return}const view=state.view;await navigate(view);toast('View reset · filters cleared · saved data unchanged')}
function login(){document.body.className='auth-body';$('#app').innerHTML=`<main class="auth-wrap"><div class="auth-brand"><span class="logo">S</span><div><b>Sentinel</b><small>SECURITY ASSURANCE</small></div></div><section class="auth-card"><div class="eyebrow">SECURE WORKSPACE</div><h1>Welcome back</h1><p>Sign in to continue to your security workspace.</p><form id="login"><label>Email address<input type="email" name="email" autocomplete="username" required autofocus></label><label>Password<input type="password" name="password" autocomplete="current-password" required></label><button class="primary full">Sign in <span>→</span></button></form><div class="auth-foot">Local, self-hosted security assessment</div></section><div class="auth-hint">First run? In the project directory, run <code>python -m security_audit --create-admin</code>.</div><div id="toast" class="toast" role="status" aria-live="polite"></div></main>`;$('#login').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const auth=await api('/auth/login',{method:'POST',body:JSON.stringify({email:f.get('email'),password:f.get('password')})});state.csrf=auth.csrf_token;sessionStorage.setItem('audit_csrf',state.csrf);await init()}catch(err){toast(err.message,true)}}}
function shell(){document.body.className='';$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><span class="logo">S</span><div><b>Sentinel</b><small>SECURITY ASSURANCE</small></div><button class="collapse" title="Collapse menu">‹</button></div><div class="org-label">WORKSPACE</div><button class="workspace" id="workspace">◈ <span>${esc(state.project?.organization||state.project?.name||'Workspace')}</span> <i>⌄</i></button><div class="org-label nav-label">ASSESSMENT</div><nav>${[['Overview','◫'],['Assets','▦'],['Findings','⌁'],['Assessments','◎'],['Compliance','◈']].map(([a,b])=>`<button class="nav-item ${state.view===a?'active':''}" data-view="${a}"><span>${b}</span>${a}${a==='Findings'?'<em id="nav-count"></em>':''}</button>`).join('')}<div class="org-label nav-label">GOVERNANCE</div>${[['Activity','↗'],['Reports','▤']].map(([a,b])=>`<button class="nav-item ${state.view===a?'active':''}" data-view="${a}"><span>${b}</span>${a}</button>`).join('')}</nav><div class="side-bottom"><div class="security-status"><span class="pulse"></span><div><b>Assessment engine</b><small>Ready · Read-only checks</small></div></div><button id="profile" class="profile"><span class="avatar">${esc((state.user.email||'U')[0].toUpperCase())}</span><span><b>${esc(state.user.email)}</b><small>Administrator</small></span><span class="more">···</span></button></div></aside><main class="main"><header class="topbar"><div class="crumb">Workspace <span>/</span> <b>${esc(state.view)}</b></div><div class="top-actions"><span class="scope">◉ <span>Shared server workspace</span></span><button class="icon-btn" title="Activity" data-view="Activity">♧</button><button class="avatar small-avatar" id="logout">${esc((state.user.email||'U')[0].toUpperCase())}</button></div></header><section class="content"><div id="view"></div></section></main><div id="toast" class="toast"></div>`;
$$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$('#logout').onclick=async()=>{try{await api('/auth/logout',{method:'POST'})}catch{}state.user=null;state.csrf='';sessionStorage.removeItem('audit_csrf');login()};$('#profile').onclick=()=>navigate('Settings');$('#workspace').onclick=()=>navigate('Settings');}
function $$(s,r=document){return [...r.querySelectorAll(s)]}
async function init(){try{const me=await api('/auth/me');state.user=me.user;if(me.csrf_token){state.csrf=me.csrf_token;sessionStorage.setItem('audit_csrf',state.csrf)}if(state.user.require_mfa&&!state.user.mfa_enabled){state.view='Security';shell();return await window.securitySettingsView()}const p=await api('/projects');state.projects=p.projects;state.project=state.projects[0]||null;shell();if(!state.project)await emptySetup();else await render()}catch(e){login()}}
async function emptySetup(){ $('#view').innerHTML=`<div class="page-head"><div><div class="eyebrow">GET STARTED</div><h1>Set up your workspace</h1><p>Create an organization and project to begin recording assessments.</p></div></div><div class="panel setup"><div class="setup-icon">◈</div><h2>Your workspace is ready</h2><p>Add an organization to scope assets, scans, controls and reports to your team.</p><form id="org-form" class="inline-form"><input name="name" placeholder="Organization name" required maxlength="120"><input name="industry" placeholder="Industry (optional)" maxlength="120"><button class="primary">Create organization</button></form></div>`;$('#org-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const o=await api('/organizations',{method:'POST',body:JSON.stringify({name:f.get('name'),industry:f.get('industry')})});await api('/projects',{method:'POST',body:JSON.stringify({organization_id:o.id,name:'Security Baseline',description:'Initial assessment project'})});await init()}catch(x){toast(x.message,true)}}}
async function navigate(v){if(state.scanTimer){clearInterval(state.scanTimer);state.scanTimer=null}state.view=v;shell();await render()}
async function render(){try{if(state.view==='Overview')return await overview();if(state.view==='Assets')return await assets();if(state.view==='Findings')return await findings();if(state.view==='Assessments')return await assessmentsView();if(state.view==='Compliance')return await compliance();if(state.view==='Activity')return await activity();if(state.view==='Reports')return reportsView();return settings()}catch(e){$('#view').innerHTML=`<div class="error-card">${esc(e.message)}</div>`}}
function head(kicker,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></div>`}
const projectQuery=()=>`?project_id=${state.project.id}`;
async function overview(){const d=await api('/dashboard'+projectQuery()),recent=await api('/findings'+projectQuery());$('#view').innerHTML=head('SECURITY POSTURE','Overview',`A live view of ${esc(state.project.name)} and its current security posture.`,`<button class="button" id="scan-local">▣ &nbsp;Assess server computer</button><button class="primary" id="scan-network">＋ &nbsp;New network assessment</button>${state.user.role==='admin'?'<button class="button danger-outline" id="reset-all-data">Reset all data</button>':''}`)+`<div class="metric-grid"><div class="metric"><div class="metric-top"><span>INVENTORIED ASSETS</span><i class="metric-icon blue">▦</i></div><div class="metric-number">${d.assets}</div><div class="metric-note">Tracked in this project</div></div><div class="metric"><div class="metric-top"><span>OPEN FINDINGS</span><i class="metric-icon amber">⌁</i></div><div class="metric-number">${d.findings}</div><div class="metric-note">Require review or remediation</div></div><div class="metric"><div class="metric-top"><span>ASSESSMENTS</span><i class="metric-icon violet">◎</i></div><div class="metric-number">${d.assessments}</div><div class="metric-note">Completed in this workspace</div></div><div class="metric risk-metric"><div class="metric-top"><span>CRITICAL / HIGH</span><i class="metric-icon red">!</i></div><div class="metric-number">${(d.severity.critical||0)+(d.severity.high||0)}</div><div class="metric-note">Prioritize these exposures</div></div></div><div class="overview-grid"><section class="panel"><div class="panel-head"><div><h2>Findings by severity</h2><p>Open items across your asset inventory</p></div><div><button class="text-btn" id="refresh-overview">Refresh</button> <button class="text-btn" data-view="Findings">View findings →</button></div></div><div class="severity-chart">${['critical','high','medium','low','info'].map(s=>`<button type="button" class="sev-row" data-severity="${s}" aria-label="Show ${s} active findings"><span class="sev-dot ${s}"></span><span class="sev-name">${s[0].toUpperCase()+s.slice(1)}</span><div class="bar-bg"><div class="bar ${s}" style="width:${Math.max(0,Math.round(100*d.severity[s]/Math.max(1,d.findings)))}%"></div></div><b>${d.severity[s]}</b></button>`).join('')}</div><div class="chart-foot"><span class="legend-dot"></span>Active findings <span class="chart-total">${d.findings} total</span></div></section><section class="panel posture"><div class="panel-head"><div><h2>Assessment coverage</h2><p>Scope progress at a glance</p></div><span class="pill neutral">LIVE</span></div><div class="coverage"><div class="donut" style="--pct:${d.assets?Math.min(100,Math.round(d.assessments/d.assets*100)):0}%"><div><b>${d.assets?Math.min(100,Math.round(d.assessments/d.assets*100)):0}%</b><small>coverage</small></div></div><div class="coverage-copy"><b>${d.assessments} assessments</b><span>across ${d.assets} inventoried assets</span><button class="text-btn" data-view="Assessments">Assessment history →</button></div></div><div class="insight"><span>✦</span><div><b>Next recommended action</b><p>${d.findings?`Review the ${d.findings} active finding${d.findings===1?'':'s'} and prioritize critical and high items.`:'Run an authorized assessment to establish your baseline.'}</p></div></div></section></div><section class="panel table-panel"><div class="panel-head"><div><h2>Recently identified findings</h2><p>Latest issues detected by completed assessments</p></div><button class="text-btn" data-view="Findings">All findings →</button></div><div id="recent-list">${findingTable(recent.findings.slice(0,5),false)}</div></section><div class="bottom-note"><span>ⓘ</span> Assessment results are point-in-time evidence. Review findings against your environment before acting.</div>`;document.querySelector('.overview-grid').insertAdjacentHTML('afterend',riskMatrixHTML(d.risk_matrix,d.risk_matrix_bands));bindNav();$('#scan-local').onclick=()=>runLocal();$('#scan-network').onclick=networkDialog;$('#refresh-overview').onclick=()=>overview().catch(e=>toast('Could not refresh dashboard: '+e.message,true));$$('.sev-row').forEach(b=>b.onclick=()=>{state.filter={...state.filter,severity:b.dataset.severity,status:'active'};navigate('Findings')});if($('#reset-all-data'))$('#reset-all-data').onclick=resetDataDialog;}
function riskMatrixHTML(matrix,bands){const impact=['Very low','Low','Moderate','High','Very high'],likelihood=['Rare','Unlikely','Possible','Likely','Almost certain'];return `<section class="panel matrix-panel"><div class="panel-head"><div><h2>Risk matrix</h2><p>Active findings counted by assessed likelihood and impact. Colors use the internal risk formula with medium asset criticality.</p></div><span class="pill neutral">5 × 5</span></div><div class="matrix-grid"><div class="matrix-corner">LIKELIHOOD ↓<br>IMPACT →</div>${impact.map(x=>`<div class="matrix-axis">${x}</div>`).join('')}${[5,4,3,2,1].map(l=>`<div class="matrix-axis row-axis">${likelihood[l-1]}</div>${[0,1,2,3,4].map(i=>`<div class="matrix-cell band-${bands?.[l-1]?.[i]||'info'}" aria-label="${likelihood[l-1]}, ${impact[i]}, ${matrix?.[l-1]?.[i]||0} findings, baseline ${bands?.[l-1]?.[i]||'info'} risk"><b>${matrix?.[l-1]?.[i]||0}</b></div>`).join('')}`).join('')}</div><div class="matrix-legend"><span><i class="heat-info"></i>Info / low</span><span><i class="heat-medium"></i>Medium</span><span><i class="heat-high"></i>High</span><span><i class="heat-critical"></i>Critical</span></div><p class="matrix-method">Each cell counts active findings. Finding score = impact × likelihood ÷ 5 × asset criticality multiplier (0–10). This internal score is separate from CVSS.</p></section>`}
function findingTable(items,editable=true){if(!items.length)return `<div class="empty"><div>✓</div><b>No findings to show</b><span>Run an assessment to identify and track security risks.</span></div>`;const statuses=['open','remediation','retest','closed','accepted','false_positive','in_progress','resolved'];return `<div class="table-scroll"><table><thead><tr><th>FINDING</th><th>ASSET</th><th>SEVERITY</th><th>RISK</th><th>STATUS</th><th>UPDATED</th>${editable?'<th></th>':''}</tr></thead><tbody>${items.map(f=>`<tr><td><button class="finding-open" data-id="${f.id}">${esc(f.title)}</button><div class="subtext">${esc(f.cve||f.category||'Security finding')}${f.verified?' · Verified evidence':' · Candidate evidence'}</div></td><td>${esc(f.asset_name||'—')}</td><td><span class="pill ${esc(f.severity)}"><i></i>${esc(f.severity)}</span></td><td><span class="risk-score" title="Internal risk: ${esc(f.risk_band||f.risk?.band||'unrated')}">${Number(f.risk_score).toFixed(1)} / 10 · ${esc(f.risk_band||f.risk?.band||'unrated')}</span></td><td><select class="status-select" data-id="${f.id}">${statuses.map(x=>`<option ${f.status===x?'selected':''} value="${x}">${x.replaceAll('_',' ')}</option>`).join('')}</select></td><td class="muted">${esc((f.updated_at||'').slice(0,10))}</td>${editable?'<td><button class="row-more" title="View evidence">↗</button></td>':''}</tr>`).join('')}</tbody></table></div>`}
async function assets(){const a=await api('/assets'+projectQuery());$('#view').innerHTML=head('INVENTORY','Assets',`Manage systems and devices included in ${esc(state.project.name)}.`,`<button class="button" id="local-asset-scan">▣ &nbsp;Assess server computer</button><button class="primary" id="add-asset">＋ &nbsp;Add asset</button>`)+`<section class="panel table-panel"><div class="filterbar"><div class="searchbox">⌕ <input id="asset-search" placeholder="Search assets by name or address"></div><span class="count-label">${a.assets.length} assets</span></div><div id="asset-table">${assetTable(a.assets)}</div></section><div class="bottom-note"><span>ⓘ</span> Authorized discovery supports private IPv4 networks up to /24 and individually authorized public IPv4 hosts (/32).</div>`;$('#local-asset-scan').onclick=runLocal;$('#add-asset').onclick=()=>assetDialog();const draw=items=>{$('#asset-table').innerHTML=assetTable(items);bindAssetActions(a.assets)};bindAssetActions(a.assets);$('#asset-search').oninput=e=>draw(a.assets.filter(x=>(x.name+x.address+x.hostname).toLowerCase().includes(e.target.value.toLowerCase())))}
function bindAssetActions(items){$$('.edit-asset').forEach(b=>b.onclick=()=>assetDialog(items.find(x=>x.id==b.dataset.id)));$$('.delete-asset').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this asset? Assessment history must not reference it.'))return;try{await api('/assets/'+b.dataset.id,{method:'DELETE'});toast('Asset deleted');assets()}catch(e){toast(e.message,true)}})}
function assetTable(items){return items.length?`<div class="table-scroll"><table><thead><tr><th>ASSET</th><th>ADDRESS / HOSTNAME</th><th>TYPE</th><th>CRITICALITY</th><th>OWNER</th><th>ADDED</th><th></th></tr></thead><tbody>${items.map(a=>`<tr><td><b>${esc(a.name)}</b></td><td>${esc(a.address||a.hostname||'—')}</td><td>${esc(a.asset_type)}</td><td><span class="pill ${a.criticality}"><i></i>${esc(a.criticality)}</span></td><td>${esc(a.owner||'—')}</td><td class="muted">${esc(a.created_at.slice(0,10))}</td><td><button class="text-btn edit-asset" data-id="${a.id}">Edit</button><button class="row-more delete-asset" data-id="${a.id}" title="Delete">×</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div>▦</div><b>No assets inventoried yet</b><span>Add a device or run a local-system assessment to begin.</span></div>`}
function assetDialog(asset=null){modal(asset?'Edit asset':'Add an asset',`<form id="asset-form" class="form-grid"><label>Asset name<input name="name" required maxlength="160" value="${esc(asset?.name||'')}"></label><label>Hostname<input name="hostname" maxlength="253" value="${esc(asset?.hostname||'')}"></label><label>IP address<input name="address" maxlength="253" value="${esc(asset?.address||'')}"></label><label>Type<select name="asset_type">${['endpoint','server','network','cloud','application'].map(x=>`<option ${x===(asset?.asset_type||'endpoint')?'selected':''}>${x}</option>`).join('')}</select></label><label>Criticality<select name="criticality">${['low','medium','high','critical'].map(x=>`<option ${x===(asset?.criticality||'medium')?'selected':''}>${x}</option>`).join('')}</select></label><label>Owner<input name="owner" maxlength="160" value="${esc(asset?.owner||'')}"></label><label class="span2">Notes<textarea name="notes" maxlength="2000">${esc(asset?.notes||'')}</textarea></label><div class="modal-actions span2"><button type="button" class="button cancel">Cancel</button><button class="primary">${asset?'Save changes':'Save asset'}</button></div></form>`);$('#asset-form').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.currentTarget));try{await api(asset?'/assets/'+asset.id:'/assets',{method:asset?'PATCH':'POST',body:JSON.stringify(asset?d:{...d,project_id:state.project.id})});closeModal();toast(asset?'Asset updated':'Asset added');assets()}catch(x){toast(x.message,true)}}}
async function findings(){const f=state.filter,params=new URLSearchParams({project_id:state.project.id,...Object.fromEntries(Object.entries(f).filter(([,v])=>v))});const data=await api('/findings?'+params);$('#view').innerHTML=head('RISK REGISTER','Findings',`Review evidence, prioritize risk and track remediation.` ,`<button class="button" id="find-export">↓ &nbsp;Export JSON</button>`)+`<section class="panel table-panel"><div class="filterbar"><div class="searchbox">⌕ <input id="find-search" placeholder="Search findings or CVEs" value="${esc(f.q)}"></div><select id="sev-filter" class="filter-select"><option value="">All severities</option>${['critical','high','medium','low','info'].map(s=>`<option value="${s}" ${f.severity===s?'selected':''}>${s[0].toUpperCase()+s.slice(1)}</option>`).join('')}</select><select id="status-filter" class="filter-select"><option value="">All statuses</option><option value="active" ${f.status==='active'?'selected':''}>All active</option>${['open','remediation','retest','in_progress','resolved','accepted','false_positive','closed'].map(s=>`<option value="${s}" ${f.status===s?'selected':''}>${s.replace('_',' ')}</option>`).join('')}</select><span class="count-label">${data.findings.length} findings</span></div><div id="find-table">${findingTable(data.findings)}</div></section><div class="bottom-note"><span>ⓘ</span> Counts include all matching records in the current project. Active excludes closed, resolved, accepted and false-positive records. Candidate software matches need vendor/version review; evidence verification does not prove exploitability.</div>`;$('#find-search').oninput=debounce(e=>{state.filter.q=e.target.value;findings()},280);$('#sev-filter').onchange=e=>{state.filter.severity=e.target.value;findings()};$('#status-filter').onchange=e=>{state.filter.status=e.target.value;findings()};bindStatuses();$('#find-export').onclick=()=>download('/reports/json'+projectQuery(),'findings.json')}
function bindStatuses(){ $$('.status-select').forEach(s=>s.onchange=async()=>{try{await api('/findings/'+s.dataset.id,{method:'PATCH',body:JSON.stringify({status:s.value})});toast('Finding workflow updated');await findings()}catch(e){toast(e.message,true);await findings()}});$$('.finding-open,.row-more').forEach(b=>{if(b.dataset.id)b.onclick=()=>findingDetail(b.dataset.id)})}
async function findingDetail(id){try{const {finding:f}=await api('/findings/'+id);modal('Finding details',`<div class="finding-detail"><span class="pill ${esc(f.severity)}"><i></i>${esc(f.severity)}</span><h3>${esc(f.title)}</h3><p>${esc(f.description||'No additional description.')}</p><div class="detail-grid"><div><small>ASSET</small><b>${esc(f.asset_name||'—')}</b></div><div><small>INTERNAL RISK SCORE</small><b>${Number(f.risk_score).toFixed(1)} / 10 · ${esc(f.risk_band||f.risk?.band||'unrated')}</b></div><div><small>LIKELIHOOD / IMPACT</small><b>${f.likelihood} / 5 · ${f.impact} / 10</b></div><div><small>STATUS</small><b>${esc(f.status.replace('_',' '))}</b></div><div><small>VERIFICATION</small><b>${f.verified?'Verified evidence':'Candidate / unverified'}</b></div>${f.cve?`<div><small>ADVISORY MATCH</small><b>${esc(f.cve)} · ${f.cve_verified||f.advisory_verified?'verified advisory match':'candidate match, not verified'}${f.cvss?` · CVSS ${esc(f.cvss)} (separate score)`:''}</b></div>`:''}</div><h4>Risk assessment</h4><p>${esc(f.risk?.explanation||'Internal risk score is based on impact and likelihood; it is separate from CVSS.')}</p><div class="risk-edit"><label>Likelihood<select id="risk-likelihood">${[1,2,3,4,5].map(x=>`<option value="${x}" ${x===f.likelihood?'selected':''}>${x} / 5</option>`).join('')}</select></label><label>Impact<select id="risk-impact">${Array.from({length:11},(_,x)=>`<option value="${x}" ${x===f.impact?'selected':''}>${x} / 10</option>`).join('')}</select></label><button class="button" id="save-risk">Recalculate risk</button></div><h4>Evidence</h4><pre class="evidence-view">${esc(JSON.stringify(f.evidence,null,2))}</pre><h4>Remediation</h4><p>${esc(f.remediation||'Review the affected asset and document an appropriate remediation.')}</p>${f.status==='retest'?`<h4>Record retest outcome</h4><form id="retest-form" class="form-grid"><label class="span2">Retest source<input name="source" required maxlength="120" placeholder="Change ticket, assessor, or validation tool"></label><label class="span2">Evidence and notes<textarea name="evidence" required maxlength="4000" placeholder="What was rechecked, when, and what was observed?"></textarea></label><label class="span2">Linked assessment ID (optional)<input name="assessment_id" type="number" min="1"></label><label class="span2">Retest outcome<select name="passed"><option value="true">Passed · close finding</option><option value="false">Failed · return to remediation</option></select></label><div class="modal-actions span2"><button type="button" class="button cancel">Cancel</button><button class="primary">Save retest evidence</button></div></form>`:''}<div class="modal-actions"><button class="primary cancel">Close</button></div></div>`);$('#save-risk').onclick=async()=>{try{await api('/findings/'+id,{method:'PATCH',body:JSON.stringify({likelihood:Number($('#risk-likelihood').value),impact:Number($('#risk-impact').value)})});closeModal();toast('Risk score updated');await render()}catch(e){toast(e.message,true)}};if($('#retest-form'))$('#retest-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{const r=await api('/findings/'+id+'/retest',{method:'POST',body:JSON.stringify({source:d.source,evidence:d.evidence,assessment_id:d.assessment_id?Number(d.assessment_id):null,passed:d.passed==='true'})});closeModal();toast(r.status==='closed'?'Retest passed · finding closed':'Retest failed · returned to remediation');await render()}catch(x){toast(x.message,true)}}}catch(e){toast(e.message,true)}}
async function queueScan(kind,options={}){try{const job=await api('/scan-jobs',{method:'POST',body:JSON.stringify({kind,project_id:state.project.id,...options})});closeModal();toast(`Assessment ${job.status} · tracking on this server`);state.view='Assessments';await navigate('Assessments')}catch(e){toast(e.message,true)}}
async function runLocal(){if(!confirm('I authorize read-only checks of the Sentinel server computer, including operating system and security settings, installed software inventory, endpoint protection, firewall, and network services. The server will continue the assessment if this browser closes.'))return;await queueScan('local',{consent_confirmed:true})}
function androidAdbDialog(){modal('Android device audit via Wi-Fi',`<div class="notice"><b>Wireless debugging pairing is required</b><span>Connect the laptop and phone to the same Wi-Fi/hotspot. On Android 11+, open Developer options → Wireless debugging → Pair device with pairing code. Pair this laptop first, then connect to the phone's Wireless debugging connection port.</span></div><p>On the laptop terminal, run <code>adb pair PHONE_IP:PAIRING_PORT</code>, enter the temporary code shown on the phone, then run <code>adb connect PHONE_IP:CONNECTION_PORT</code>. This authorizes this workstation. Sentinel will query only that paired private IP and port.</p><p>Collected: model, Android version, security patch, selected security settings, and third-party package names/versions. App data, files, photos, messages, contacts, credentials and browsing history are not read. Some checks are unavailable on some devices; this is not a complete device scan.</p><form id="android-adb-form" class="form-grid"><label>Phone private IPv4<input name="ip" inputmode="decimal" placeholder="192.168.43.1" required maxlength="15"></label><label>Wireless debugging connection port<input name="port" inputmode="numeric" placeholder="37099" required maxlength="5"></label><label class="checkline span2"><input type="checkbox" name="authorized" required> This is my phone or one I am authorized to audit; I paired this laptop using the phone's displayed pairing code.</label><div class="modal-actions span2"><button type="button" class="button cancel">Cancel</button><button class="primary">Start Android audit</button></div></form>`);$('#android-adb-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),ip=String(f.get('ip')||'').trim(),port=String(f.get('port')||'').trim(),button=$('button.primary',form);const octets=ip.split('.');if(octets.length!==4||octets.some(x=>!/^\d{1,3}$/.test(x)||Number(x)>255||x.length>1&&x.startsWith('0'))){toast('Enter one valid private IPv4 address',true);return}const nums=octets.map(Number),privateIp=nums[0]===10||nums[0]===172&&nums[1]>=16&&nums[1]<=31||nums[0]===192&&nums[1]===168;if(!privateIp){toast('Wireless ADB is limited to an RFC1918 private IPv4 address',true);return}const n=Number(port);if(!/^\d{1,5}$/.test(port)||n<1||n>65535){toast('Enter the Wireless debugging connection port shown by Android',true);return}button.disabled=true;button.textContent='Queueing…';await queueScan('android_adb',{target:ip+':'+n,consent_confirmed:true})}}
function networkDialog(){modal('Authorized network assessment',`<div class="notice"><b>Authorization required</b><span>Single hosts use full TCP discovery and service detection when Nmap is installed. Networks use host discovery before detailed assessment of responsive hosts. UDP checks are bounded. Collection is read-only: no exploitation, login attempts or configuration changes. Public scope requires one globally routable IPv4 /32.</span></div><form id="network-form" class="form-grid"><label class="span2">IPv4 address or CIDR<input name="target" placeholder="192.168.1.0/24 or a literal authorized IPv4 address" required maxlength="253"><small>Private/loopback IPv4 networks up to /24; public scope requires one literal globally routable IPv4 /32. Documentation/test IPs are blocked.</small><small>A bare IPv4 address assesses only that host (/32). A CIDR assesses only the addresses inside that network. No gateway or neighboring device is added automatically. Ping is not used; firewalls or hotspot isolation may limit the evidence collected.</small></label><label class="checkline span2"><input type="checkbox" name="authorized" required> I confirm I am authorized to assess this exact target and scope.</label><label class="checkline span2"><input type="checkbox" name="public_authorized"> This is a public IP and I have explicit authorization from its owner.</label><div class="modal-actions span2"><button type="button" class="button cancel">Cancel</button><button class="primary">Queue assessment</button></div></form>`);$('#network-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),b=$('button.primary',e.currentTarget);b.disabled=true;b.textContent='Queueing…';await queueScan('network',{target:f.get('target'),authorized:!!f.get('authorized'),public_authorized:!!f.get('public_authorized')})}}
function scanJobScopeSummary(j){if(j.result?.device_summary){const d=j.result.device_summary;return '<div class="subtext">'+esc((d.manufacturer+' '+d.model).trim())+' · Android '+esc(d.android_version)+' · '+d.visible_app_count+' launcher-visible apps · '+d.checks_completed+' checks completed</div>'}if(j.result?.network_summary)return '<div class="subtext">Hosts '+j.result.network_summary.hosts_discovered+' discovered · '+j.result.network_summary.hosts_uncertain+' uncertain · '+j.result.network_summary.exposed_ports+' exposed ports · Sentinel risk '+j.result.network_summary.total_sentinel_risk+'</div>';return ''}
function scanJobsMarkup(jobs){return jobs.length?`<section class="panel table-panel"><div class="panel-head"><div><h2>Scan activity</h2><p>Persistent server-side job state · refreshed from the API</p></div></div><div class="table-scroll"><table><thead><tr><th>SCAN</th><th>SCOPE</th><th>STATUS</th><th>PROGRESS</th><th>MESSAGE / ERROR</th><th></th></tr></thead><tbody>${jobs.map(j=>`<tr><td><b>${esc(j.kind==='android_device'?'Android device audit':j.kind==='android_adb'?'Android Wi-Fi ADB audit':j.kind==='local'?'Local system':'Network')}</b><div class="subtext">${esc(j.created_at)} · ${esc(j.id.slice(0,8))}</div></td><td>${esc(j.target||'This server')}${scanJobScopeSummary(j)}</td><td><span class="pill ${j.status==='failed'?'high':j.status==='completed'?'low':'medium'}"><i></i>${esc(j.status)}</span></td><td>${j.progress}%</td><td>${esc(j.error||j.message)}${j.result?.warnings?.length?`<div class="subtext">${esc(j.result.warnings.join(" · "))}</div>`:""}</td><td>${['queued','running'].includes(j.status)?`<button class="button cancel-scan" data-id="${j.id}">Cancel</button>`:['failed','cancelled'].includes(j.status)?`<button class="button retry-scan" data-id="${j.id}">Retry</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`:`<section class="panel"><div class="empty"><div>◎</div><b>No scans queued</b><span>Completed assessments appear in history below.</span></div></section>`}
async function refreshScanJobs(){const el=$('#scan-jobs');if(!el||state.view!=='Assessments')return;try{const x=await api('/scan-jobs'+projectQuery());el.outerHTML=`<div id="scan-jobs">${scanJobsMarkup(x.jobs)}</div>`;$$('.cancel-scan').forEach(b=>b.onclick=async()=>{try{await api('/scan-jobs/'+b.dataset.id,{method:'DELETE'});await refreshScanJobs()}catch(e){toast(e.message,true)}});$$('.retry-scan').forEach(b=>b.onclick=async()=>{try{await api('/scan-jobs/'+b.dataset.id+'/retry',{method:'POST',body:'{}'});await refreshScanJobs()}catch(e){toast(e.message,true)}})}catch(e){toast('Could not refresh scan status: '+e.message,true)}}
async function assessmentsView(){if(state.scanTimer)clearInterval(state.scanTimer);const [x,j]=await Promise.all([api('/assessments'+projectQuery()),api('/scan-jobs'+projectQuery())]);$('#view').innerHTML=head('ASSESSMENT HISTORY','Assessments','Review completed checks, active jobs and comparison history.',`<button class="button" id="history-local">▣ &nbsp;Assess server computer</button><button class="button" id="history-android-adb">Android via Wi-Fi ADB</button><button class="primary" id="history-network">＋ &nbsp;Network assessment</button>`)+`<div id="scan-jobs">${scanJobsMarkup(j.jobs)}</div><section class="panel table-panel"><div class="panel-head"><div><h2>Completed assessments</h2><p>Point-in-time snapshots of saved evidence and findings</p></div><span class="count-label">${x.assessments.length} records</span></div>${x.assessments.length?`<div class="table-scroll"><table><thead><tr><th>ASSESSMENT</th><th>STARTED</th><th>COMPLETED</th><th>FINDINGS</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${x.assessments.map(a=>`<tr><td><b>${a.kind==='android_device'?'Android device audit':a.kind==='local'?'Local system review':'Authorized network review'}</b><div class="subtext">Assessment #${a.id}</div></td><td>${esc(a.started_at)}</td><td>${esc(a.completed_at)}</td><td>${a.summary.findings?.length??0}</td><td><span class="pill low"><i></i>${esc(a.status)}</span></td><td><button class="text-btn assessment-report" data-id="${a.id}">Download PDF</button> <button class="text-btn compare" data-id="${a.id}">Compare</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div>◎</div><b>No assessments completed</b><span>Run a local or authorized network assessment to create a baseline.</span></div>`}</section>`;$('#history-local').onclick=runLocal;$('#history-android-adb').onclick=androidAdbDialog;$('#history-network').onclick=networkDialog;$$('.compare').forEach(b=>b.onclick=()=>compareDialog(b.dataset.id,x.assessments));$$('.assessment-report').forEach(b=>b.onclick=()=>downloadAssessmentPdf(Number(b.dataset.id)));$$('.cancel-scan').forEach(b=>b.onclick=async()=>{try{await api('/scan-jobs/'+b.dataset.id,{method:'DELETE'});await refreshScanJobs()}catch(e){toast(e.message,true)}});$$('.retry-scan').forEach(b=>b.onclick=async()=>{try{await api('/scan-jobs/'+b.dataset.id+'/retry',{method:'POST',body:'{}'});await refreshScanJobs()}catch(e){toast(e.message,true)}});state.scanTimer=setInterval(refreshScanJobs,1500)}
function downloadAssessmentPdf(id){if(!Number.isInteger(id)||id<1){toast('Invalid assessment ID',true);return}const params=new URLSearchParams({project_id:String(state.project.id),type:'technical',assessment_id:String(id)});download(`/reports/pdf?${params}`,`security-technical-assessment-${id}.pdf`)}
function compareDialog(id,all){const prev=all.find(a=>a.id!=id);if(!prev){toast('Complete another assessment to compare results');return}api(`/compare?project_id=${state.project.id}&ids=${prev.id},${id}`).then(r=>{const a=JSON.stringify(r.earlier.summary),b=JSON.stringify(r.later.summary);modal('Assessment comparison',`<div class="compare-grid"><div><span class="eyebrow">ASSESSMENT #${r.earlier.id}</span><h3>${esc(r.earlier.kind)} · ${esc(r.earlier.completed_at)}</h3><p>${r.earlier.summary.findings?.length||0} recorded findings</p><div class="compare-data">${esc(a.slice(0,900))}</div></div><div><span class="eyebrow">ASSESSMENT #${r.later.id}</span><h3>${esc(r.later.kind)} · ${esc(r.later.completed_at)}</h3><p>${r.later.summary.findings?.length||0} recorded findings</p><div class="compare-data">${esc(b.slice(0,900))}</div></div></div><div class="modal-actions"><button class="primary cancel">Close</button></div>`)}).catch(e=>toast(e.message,true))}
async function compliance(){const x=await api('/controls'+projectQuery());const frameworks=[...new Set(x.controls.map(c=>c.framework))];$('#view').innerHTML=head('GOVERNANCE','Compliance & controls','Map assessment evidence to configurable security frameworks.',`<button class="primary" id="add-control">＋ &nbsp;Add control</button>`)+`<div class="framework-summary">${frameworks.map(f=>`<div class="framework-card"><span class="metric-icon blue">◈</span><div><b>${esc(f)}</b><small>${x.controls.filter(c=>c.framework===f).length} mapped controls</small></div></div>`).join('')}</div><section class="panel table-panel"><div class="panel-head"><div><h2>Control assessment</h2><p>Record implementation status and supporting evidence</p></div><span class="pill neutral">${x.controls.length} CONTROLS</span></div><div class="table-scroll"><table><thead><tr><th>FRAMEWORK / CONTROL</th><th>CONTROL</th><th>ASSESSMENT STATUS</th><th>EVIDENCE / NOTES</th></tr></thead><tbody>${x.controls.map(c=>`<tr><td><b>${esc(c.framework)}</b><div class="subtext">${esc(c.control_key)}</div></td><td><div class="finding-title">${esc(c.title)}</div><div class="subtext">${esc(c.description)}</div></td><td><select class="control-status" data-id="${c.id}">${['not_assessed','implemented','partial','not_implemented','not_applicable'].map(s=>`<option value="${s}" ${c.status===s?'selected':''}>${s.replace('_',' ')}</option>`).join('')}</select></td><td><input class="control-evidence" data-id="${c.id}" value="${esc(c.evidence)}" placeholder="Evidence reference or note"></td></tr>`).join('')}</tbody></table></div></section><div class="bottom-note"><span>ⓘ</span> Control status is assessor-recorded and is not automatically certified by scanner output.</div>`;$$('.control-status').forEach(s=>s.onchange=()=>saveControl(s.dataset.id));$$('.control-evidence').forEach(s=>s.onchange=()=>saveControl(s.dataset.id));$('#add-control').onclick=controlDialog}
function controlDialog(){modal('Add a framework control',`<form id="control-form" class="form-grid"><label>Framework<input name="framework" required maxlength="80" placeholder="NIST CSF 2.0"></label><label>Control identifier<input name="control_key" required maxlength="80" placeholder="PR.AA-01"></label><label class="span2">Control title<input name="title" required maxlength="240"></label><label class="span2">Description<textarea name="description" maxlength="2000"></textarea></label><div class="modal-actions span2"><button type="button" class="button cancel">Cancel</button><button class="primary">Add control</button></div></form>`);$('#control-form').onsubmit=async e=>{e.preventDefault();try{await api('/controls',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(e.currentTarget)),project_id:state.project.id})});closeModal();toast('Control added');compliance()}catch(x){toast(x.message,true)}}}
async function saveControl(id){const status=$(`.control-status[data-id="${id}"]`).value,evidence=$(`.control-evidence[data-id="${id}"]`).value;try{await api('/controls',{method:'PATCH',body:JSON.stringify({project_id:state.project.id,control_id:Number(id),status,evidence})});toast('Control assessment saved')}catch(e){toast(e.message,true)}}
async function activity(){const x=await api('/audit'+projectQuery());$('#view').innerHTML=head('GOVERNANCE','Activity log','An auditable timeline of assessment and risk register changes.')+`<section class="panel table-panel"><div class="panel-head"><div><h2>Recent activity</h2><p>Latest 200 recorded events</p></div></div>${x.events.length?`<div class="table-scroll"><table><thead><tr><th>ACTOR</th><th>ACTIVITY</th><th>ENTITY</th><th>DETAILS</th><th>TIME (UTC)</th></tr></thead><tbody>${x.events.map(e=>`<tr><td>${esc(e.email||'System')}</td><td><b>${esc(e.action.replaceAll('.',' '))}</b></td><td>${esc(e.entity)} ${e.entity_id||''}</td><td>${esc(JSON.stringify(e.details))}</td><td class="muted">${esc(e.created_at)}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div>↗</div><b>No activity recorded</b><span>Assessment and workflow events will appear here.</span></div>`}</section>`}
function reportsView(){$('#view').innerHTML=head('REPORTING','Project-wide reports','These reports summarize the selected project. Download an individual assessment PDF from Assessment History.')+`<div class="report-grid">${[['Executive summary','A concise view of open exposure, priority risks and assessment coverage.','executive'],['Technical security report','Finding-level evidence, severity, risk score and remediation guidance.','technical']].map(([t,d,id])=>`<section class="panel report-card"><div class="report-icon">▤</div><span class="eyebrow">${id==='executive'?'LEADERSHIP':'SECURITY TEAM'}</span><h2>${t}</h2><p>${d}</p><div class="report-actions"><button class="button export" data-type="${id}" data-format="json">↓ JSON</button><button class="primary export" data-type="${id}" data-format="pdf">↓ PDF report</button></div></section>`).join('')}</div><section class="panel report-info"><div class="report-icon small-report">ⓘ</div><div><b>Evidence-led reporting</b><p>Reports distinguish verified collection evidence from candidate advisory matches. Treat findings as point-in-time results and review before distribution.</p></div></section>`;$$('.export').forEach(b=>b.onclick=()=>download(`/reports/${b.dataset.format}${projectQuery()}&type=${b.dataset.type}`,`security-${b.dataset.type}-report.${b.dataset.format}`))}
async function settings(){const org=await api('/organizations');$('#view').innerHTML=head('WORKSPACE','Settings','Manage the assessment workspace and project scope.')+`<section class="panel settings-panel"><div class="panel-head"><div><h2>Organization & projects</h2><p>Assessments and evidence are scoped to the selected project.</p></div></div><div class="setting-row"><div><b>Current project</b><span>${esc(state.project.name)} · ${esc(state.project.organization)}</span></div><select id="project-switch">${state.projects.map(p=>`<option value="${p.id}" ${p.id===state.project.id?'selected':''}>${esc(p.organization)} / ${esc(p.name)}</option>`).join('')}</select></div><div class="setting-row"><div><b>Create project</b><span>Add an assessment scope within an organization.</span></div><button class="button" id="new-project">＋ New project</button></div><div class="setting-row"><div><b>Create organization</b><span>Use separate organizations to scope access and data.</span></div><button class="button" id="new-org">＋ New organization</button></div><div class="setting-row"><div><b>Assessment templates</b><span>Reusable profiles for common review types.</span></div><div><button class="button" id="show-templates">View templates</button> <button class="button" id="new-template">＋ New template</button></div></div><div class="setting-row"><div><b>Organization access</b><span>Grant project read-only or analyst access in this workspace.</span></div><button class="button" id="invite-user">＋ Add user</button></div>${state.user.role==='admin'?'<div class="setting-row"><div><b>Delete all saved assessment data</b><span>Remove assessments, findings, evidence, assets, control results and previous activity across all organizations and projects.</span></div><button class="button danger-outline" id="reset-data">Delete all data</button></div>':''}<div class="setting-row"><div><b>Password</b><span>Change your password using your current password and a new password of at least 6 characters.</span></div><button class="button" id="change-password">Change password</button></div><div class="setting-row"><div><b>Session</b><span>${esc(state.user.email)} · ${state.user.role==='admin'?'administrator':'workspace member'}</span></div><button class="button danger-outline" id="settings-logout">Sign out</button></div></section><section class="panel settings-panel"><div class="panel-head"><div><h2>Assessment safety boundaries</h2><p>Local checks are read-only. Private IPv4 scopes are limited to /24; public scanning is limited to one globally routable IPv4 /32. Every network assessment requires explicit authorization.</p></div></div><div class="setting-row"><div><b>Network method</b><span>Single-host scopes use installed Nmap for full TCP discovery, lightweight service/version detection and bounded UDP checks. Networks use Nmap host discovery before detailed checks on responsive hosts; without Nmap, a bounded common-port fallback is used. All collection is read-only.</span></div><span class="pill low"><i></i>READ ONLY</span></div><div class="setting-row"><div><b>Evidence provenance</b><span>Each finding records its source and whether the observation was verified or advisory candidate.</span></div><span class="pill neutral">ENABLED</span></div></section>`;$('#project-switch').onchange=e=>{state.project=state.projects.find(p=>p.id==e.target.value);navigate('Overview')};$('#new-org').onclick=orgDialog;$('#new-project').onclick=()=>projectDialog(org.organizations);$('#new-template').onclick=templateDialog;$('#invite-user').onclick=()=>userDialog(org.organizations);if($('#reset-data'))$('#reset-data').onclick=resetDataDialog;$('#show-templates').onclick=async()=>{const t=await api('/templates');modal('Assessment templates',`<div class="template-list">${t.templates.map(t=>`<article><b>${esc(t.name)}</b><p>${esc(t.description)}</p><small>${esc(JSON.parse(t.checks).join(' · '))}</small></article>`).join('')}</div><div class="modal-actions"><button class="primary cancel">Done</button></div>`)};$('#change-password').onclick=passwordDialog;$('#settings-logout').onclick=$('#logout').onclick}
function passwordDialog(){modal('Change password',`<form id="password-form" class="form-grid"><label class="span2">Current password<input type="password" name="current_password" autocomplete="current-password" required maxlength="256"></label><label class="span2">New password<input type="password" name="new_password" autocomplete="new-password" required minlength="6" maxlength="256"><small>Use at least 6 characters. Do not use a short, common password.</small></label><label class="span2">Confirm new password<input type="password" name="confirm_password" autocomplete="new-password" required minlength="6" maxlength="256"></label><div class="modal-actions span2"><button type="button" class="button cancel">Cancel</button><button class="primary">Update password</button></div></form>`);$('#password-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));if(data.new_password!==data.confirm_password){toast('New passwords do not match',true);return}try{await api('/auth/change-password',{method:'POST',body:JSON.stringify(data)});e.currentTarget.reset();closeModal();toast('Password changed. Other signed-in sessions were revoked.')}catch(error){toast(error.message,true)}}}
function resetDataDialog(){if(state.user.role!=='admin'){toast('Administrator access required',true);return}const phrase='ERASE ALL SAVED ASSESSMENT DATA';modal('Delete all saved data',`<div class="notice reset-warning"><b>This cannot be undone</b><span>This clears dashboard totals for assets, findings, assessments, and critical/high risks to zero by removing every asset, assessment, finding, evidence record, control result and previous activity log entry across all organizations and projects. User accounts, organization and project names, templates, and framework controls will remain. A new audit event will record this reset.</span></div><form id="reset-form"><label class="reset-label">Type <code>${phrase}</code> to confirm<input id="reset-confirmation" autocomplete="off" required></label><div class="modal-actions"><button type="button" class="button cancel">Cancel</button><button class="primary danger-button" id="reset-submit" disabled>Erase all saved data</button></div></form>`);const input=$('#reset-confirmation'),submit=$('#reset-submit');input.oninput=()=>submit.disabled=input.value!==phrase;$('#reset-form').onsubmit=async e=>{e.preventDefault();if(input.value!==phrase)return;submit.disabled=true;submit.textContent='Erasing…';try{await api('/reset',{method:'POST',body:JSON.stringify({confirmation:input.value})});closeModal();toast('Saved assessment data erased');state.view='Overview';await init()}catch(err){submit.disabled=false;submit.textContent='Erase all saved data';toast(err.message,true)}}}
function userDialog(orgs){if(state.user.role!=='admin'){toast('Administrator access required',true);return}modal('Add organization user',`<form id="user-form" class="form-grid"><label class="span2">Email address<input type="email" name="email" required maxlength="254"></label><label class="span2">Initial password<input type="password" name="password" required minlength="6" maxlength="256"><small>Minimum 6 characters. Share it through your approved secure channel.</small></label><label class="span2">Organization<select name="organization_id">${orgs.map(o=>`<option value="${o.id}">${esc(o.name)}</option>`).join('')}</select></label><label class="span2">Access role<select name="organization_role"><option value="viewer">Viewer · read only</option><option value="analyst">Analyst · assess and update</option><option value="admin">Administrator · manage workspace</option></select></label><div class="modal-actions span2"><button class="button cancel" type="button">Cancel</button><button class="primary">Create user</button></div></form>`);$('#user-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{await api('/users',{method:'POST',body:JSON.stringify({...d,organization_id:Number(d.organization_id)})});closeModal();toast('Organization user created')}catch(x){toast(x.message,true)}}}
function templateDialog(){modal('Create assessment template',`<form id="template-form" class="form-grid"><label class="span2">Template name<input name="name" required maxlength="120"></label><label class="span2">Description<textarea name="description" maxlength="2000"></textarea></label><label class="span2">Review checks<small>Comma-separated checklist items</small><input name="checks" placeholder="Asset inventory, secure configuration, evidence review"></label><div class="modal-actions span2"><button type="button" class="button cancel">Cancel</button><button class="primary">Create template</button></div></form>`);$('#template-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.checks=d.checks.split(',').map(x=>x.trim()).filter(Boolean);try{await api('/templates',{method:'POST',body:JSON.stringify(d)});closeModal();toast('Template created')}catch(x){toast(x.message,true)}}}
function orgDialog(){modal('Create organization',`<form id="org-create" class="form-grid"><label class="span2">Organization name<input name="name" required maxlength="120"></label><label class="span2">Industry<input name="industry" maxlength="120"></label><div class="modal-actions span2"><button class="button cancel" type="button">Cancel</button><button class="primary">Create</button></div></form>`);$('#org-create').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await api('/organizations',{method:'POST',body:JSON.stringify({name:f.get('name'),industry:f.get('industry')})});closeModal();toast('Organization created');init()}catch(x){toast(x.message,true)}}}
function projectDialog(orgs){modal('Create project',`<form id="project-create" class="form-grid"><label class="span2">Organization<select name="organization_id">${orgs.map(o=>`<option value="${o.id}">${esc(o.name)}</option>`).join('')}</select></label><label class="span2">Project name<input name="name" required maxlength="120"></label><label class="span2">Description<textarea name="description" maxlength="2000"></textarea></label><div class="modal-actions span2"><button class="button cancel" type="button">Cancel</button><button class="primary">Create project</button></div></form>`);$('#project-create').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{await api('/projects',{method:'POST',body:JSON.stringify(d)});closeModal();toast('Project created');init()}catch(x){toast(x.message,true)}}}
function modal(title,html){closeModal();const div=document.createElement('div');div.className='modal-backdrop';div.id='modal';div.innerHTML=`<section class="modal"><div class="modal-head"><h2>${title}</h2><button class="close-modal">×</button></div><div class="modal-body">${html}</div></section>`;document.body.append(div);$('.close-modal').onclick=closeModal;$$('.cancel',div).forEach(b=>b.addEventListener('click',closeModal));div.onclick=e=>{if(e.target===div)closeModal()}}
function closeModal(){$('#modal')?.remove()}
function bindNav(){$$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view))}
function download(path,name){if(window.SentinelAndroid&&typeof window.SentinelAndroid.requestReportDownload==='function'){window.SentinelAndroid.requestReportDownload('/api'+path,name);return}fetch('/api'+path,{credentials:'same-origin'}).then(r=>{if(!r.ok)throw Error('Report could not be generated');return r.blob()}).then(blob=>{const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();URL.revokeObjectURL(a.href);toast('Report downloaded')}).catch(e=>toast(e.message,true))}
function debounce(fn,ms){let t;return(...args)=>{clearTimeout(t);t=setTimeout(()=>fn(...args),ms)}}
document.addEventListener('DOMContentLoaded',()=>init());
function androidAuditAvailable(){return Boolean(state.user&&state.project&&window.SentinelAndroid&&typeof window.SentinelAndroid.requestAndroidDeviceAudit==='function')}
window.SentinelAudit=window.SentinelAudit||{};
window.SentinelAudit.onAndroidDeviceAuditCollected=payload=>{
 if(!androidAuditAvailable()){toast('Sign in to a project before submitting the Android device audit.',true);return}
 queueScan('android_device',{consent_confirmed:true,device_audit:payload});
};
document.addEventListener('DOMContentLoaded',()=>{
 const appRoot=document.getElementById('app');
 if(!appRoot)return;
 const addAndroidAuditAction=()=>{
  if(!androidAuditAvailable())return;
  const actions=document.querySelector('#view .page-head .head-actions');
  if(!actions||document.getElementById('android-device-audit'))return;
  const button=document.createElement('button');
  button.id='android-device-audit';button.className='button';button.type='button';button.textContent='Audit this Android device';
  button.addEventListener('click',()=>window.SentinelAndroid.requestAndroidDeviceAudit());
  actions.appendChild(button);
 };
 new MutationObserver(addAndroidAuditAction).observe(appRoot,{childList:true,subtree:true});
 addAndroidAuditAction();
});
